        ani_change annealing(ani_change now,vector<vector<short>> o,int num,int n){
            ld start=0.2*num*n,end=0.5;
            ani_change max_score=now;
            if (st>0) start=st;
            while(clock() < 4.90 * CLOCKS_PER_SEC*time/(ld)100){
                ld prog=(4.90 * CLOCKS_PER_SEC*time/(ld)100-clock())/(4.90 * CLOCKS_PER_SEC/(ld)100);
                ld temp=end+(start-end)*prog;
                short r1=mt()%num,r2=mt()%num;
                if (r1==r2) continue;
                short r3=mt()%n,r4=mt()%n;
                short f=now.group[r1][r3],g=now.group[r2][r4];
                int sc1=0,sc2=0;
                vector<short> dot1=now.dot[r1],dot2=now.dot[r2];
                rep(i,num*n){
                    dot1[i]-=o[f][i]-o[g][i];
                    dot2[i]+=o[f][i]-o[g][i];
                    sc1+=min(dot1[i],(short)(n-dot1[i]));
                    sc2+=min(dot2[i],(short)(n-dot2[i]));
                }
                short diffscore=(now.sum[r1]-sc1)+(now.sum[r2]-sc2);
                if (temp<0.5 && diffscore<-2){
                    continue;
                }
                ld prob = exp((ld)diffscore/temp);
                if (prob>(ld)mt()/(ld)mt.max()){
                    now.score-=diffscore;
                    now.sum[r1]=sc1;
                    now.sum[r2]=sc2;
                    swap(now.group[r1][r3],now.group[r2][r4]);
                    now.dot[r1]=dot1;
                    now.dot[r2]=dot2;
                    if (now.score<max_score.score){
                        max_score=now;
                    }
                }
            }
            return max_score;
        }

        ani_change annealing2(ani_change now,vector<vector<short>> o,int num,int n){
            ld start=0.2*num*n,end=0.5;
            ani_change max_score=now;
            if (st>0) start=st;
            while(clock() < 4.90 * CLOCKS_PER_SEC*time/(ld)100){
                ld prog=(4.90 * CLOCKS_PER_SEC*time/(ld)100-clock())/(4.90 * CLOCKS_PER_SEC/(ld)100);
                ld temp=end+(start-end)*prog;
                short r1=mt()%num,r2=mt()%num;
                if (r1==r2) continue;
                short r3=mt()%n,r4=mt()%n;
                short f=now.group[r1][r3],g=now.group[r2][r4];
                int sc1=0,sc2=0;
                rep(i,num*n){
                    sc1+=min((short)(now.dot[r1][i]+o[g][i]-o[f][i]),(short)(n*2-(now.dot[r1][i]+o[g][i]-o[f][i])));
                    sc2+=min((short)(now.dot[r2][i]+o[f][i]-o[g][i]),(short)(n*2-(now.dot[r2][i]+o[f][i]-o[g][i])));
                }
                short diffscore=(now.sum[r1]-sc1)+(now.sum[r2]-sc2);
                if (temp<0.5 && diffscore<-2){
                    continue;
                }
                ld prob = exp((ld)diffscore/temp);
                if (prob>(ld)mt()/(ld)mt.max()){
                    now.score-=diffscore;
                    now.sum[r1]=sc1;
                    now.sum[r2]=sc2;
                    swap(now.group[r1][r3],now.group[r2][r4]);
                    rep(i,num*n){
                        now.dot[r1][i]-=o[f][i]-o[g][i];
                        now.dot[r2][i]+=o[f][i]-o[g][i];
                    }
                    if (now.score<max_score.score){
                        max_score=now;
                    }
                }
            }
            return max_score;
        }


