            vector<vector<short>> o(num*n,vector<short>(num*n,2));
            int c=0;
            rep(i,num*n){
                for (int j=i+1;j<num*n;j++){
                    if (s[c]=='0'){
                        o[i][j]=0;
                        o[j][i]=0;
                    }
                    c++;
                }
                o[i][i]=1;
            }

            vector<vector<short>> group(num,vector<short>(n));
            vector<vector<short>> dot(num,vector<short>(num*n,0));
            vector<short> sum(num,0);
